// SCENE 1: Map with 48 pins, one turns red & bigger
// =====================================================
const Scene1Map: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // Generate 48 pin positions deterministically
  const pins = React.useMemo(() => {
    const arr: { x: number; y: number; seed: string }[] = [];
    let s = 1;
    const rnd = () => {
      s = (s * 9301 + 49297) % 233280;
      return s / 233280;
    };
    for (let i = 0; i < 48; i++) {
      arr.push({
        x: 10 + rnd() * 80,
        y: 14 + rnd() * 72,
        seed: `pin-${i}`,
      });
    }
    return arr;
  }, []);

  const mapIn = springIn(frame, vfps, 4, "LIQUID");
  const mapSc = interpolate(mapIn, [0, 1], [0.94, 1]);
  const mapTy = interpolate(mapIn, [0, 1], [30, 0]);

  // The "problem" pin index
  const badIdx = 27;

  const redTrigger = springIn(frame, vfps, 38, "SNAPPY");

  const driftX = ambientDrift(frame, 2, 110, "map-x");
  const driftY = ambientDrift(frame, 2, 130, "map-y");

  return (
    <AbsoluteFill>
      <Background />
      <AbsoluteFill
        style={{
          padding: base * 0.06,
          opacity: mapIn,
          transform: `translate(${driftX}px, ${mapTy + driftY}px) scale(${mapSc})`,
        }}
      >
        {/* Map card */}
        <div
          style={{
            position: "absolute",
            inset: `${base * 0.08}px ${base * 0.1}px`,
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.02,
            overflow: "hidden",
            boxShadow: "0 24px 64px rgba(0,0,0,0.5)",
          }}
        >
          {/* World map silhouette */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              opacity: 0.18,
              filter: "blur(0.5px)",
            }}
          >
            <Img
              src={staticFile("assets/other/world.svg")}
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                filter: "invert(1) brightness(0.4)",
              }}
            />
          </div>

          {/* Grid overlay */}
          <svg
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              opacity: 0.08,
            }}
          >
            {Array.from({ length: 10 }).map((_, i) => (
              <line
                key={`v${i}`}
                x1={i * 10}
                y1={0}
                x2={i * 10}
                y2={100}
                stroke={COLORS.orange}
                strokeWidth={0.1}
              />
            ))}
            {Array.from({ length: 10 }).map((_, i) => (
              <line
                key={`h${i}`}
                x1={0}
                y1={i * 10}
                x2={100}
                y2={i * 10}
                stroke={COLORS.orange}
                strokeWidth={0.1}
              />
            ))}
          </svg>

          {/* Pins */}
          {pins.map((pin, i) => {
            const isBad = i === badIdx;
            const pinIn = staggeredSpring(
              frame,
              vfps,
              i,
              10,
              0.6,
              "ELASTIC"
            );
            const pulse = ambientDrift(frame, 0.4, 50, pin.seed);

            // Bad pin grows + turns red
            const badGrow = isBad ? redTrigger : 0;
            const baseSize = base * 0.014;
            const size = isBad
              ? baseSize + interpolate(badGrow, [0, 1], [0, base * 0.022])
              : baseSize;
            const color = isBad
              ? interpolate(badGrow, [0, 1], [0, 1]) > 0.5
                ? COLORS.orangeDeep
                : COLORS.orange
              : COLORS.orange;

            // Ring pulse for bad pin
            const ringScale = isBad
              ? 1 + ((frame - 38) % 30) / 30
              : 1;
            const ringOp = isBad
              ? Math.max(0, 1 - ((frame - 38) % 30) / 30) * 0.6 * badGrow
              : 0;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: `${pin.x}%`,
                  top: `${pin.y}%`,
                  transform: `translate(-50%, -50%) scale(${pinIn})`,
                }}
              >
                {isBad && (
                  <div
                    style={{
                      position: "absolute",
                      left: "50%",
                      top: "50%",
                      width: size * 3,
                      height: size * 3,
                      borderRadius: "50%",
                      background: COLORS.orangeDeep,
                      transform: `translate(-50%, -50%) scale(${ringScale})`,
                      opacity: ringOp,
                    }}
                  />
                )}
                <div
                  style={{
                    width: size + pulse,
                    height: size + pulse,
                    borderRadius: "50%",
                    background: color,
                    border: isBad
                      ? `${base * 0.003}px solid ${COLORS.text}`
                      : `${base * 0.0015}px solid rgba(255,255,255,0.4)`,
                    boxShadow: isBad
                      ? `0 0 ${base * 0.02}px ${COLORS.orangeDeep}`
                      : "none",
                  }}
                />
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

