                ? interpolate(alertProg, [0, 1], [1, 1.5])
                : 1;

              // In peaceful state, alerts stay highlighted but pulse calmly,
              // others stay muted
              const baseOpacity = pin.isAlert
                ? 1
                : 0.5 + 0.1 * (1 - peaceful);

              return (
                <div
                  key={i}
                  style={{
                    aspectRatio: "1",
                    background: pin.isAlert
                      ? interpolate(alertProg, [0, 1], [0, 1]) > 0.5
                        ? COLORS.orangeDeep
                        : "rgba(255,255,255,0.08)"
                      : "rgba(255,255,255,0.06)",
                    border: pin.isAlert
                      ? `1.5px solid ${COLORS.orange}`
                      : `1px solid ${COLORS.border}`,
                    borderRadius: base * 0.004,
                    opacity: pinIn * baseOpacity,
                    transform: `scale(${pinIn * grow})`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: pin.isAlert && alertProg > 0.5
                      ? `0 0 ${base * 0.015}px rgba(248,102,6,${0.4 * alertProg})`
                      : "none",
                  }}
                >
                  {pin.isAlert && alertProg > 0.3 && (
                    <div
                      style={{
                        width: "30%",
                        height: "30%",
                        borderRadius: "50%",
                        background: COLORS.text,
                        opacity: alertProg,
                      }}
                    />
                  )}
                </div>
              );
            })}
          </div>

          {/* Bottom status row */}
          <div
            style={{
              display: "flex",
              gap: base * 0.014,
              alignItems: "center",
            }}
          >
            {/* Needs attention badge */}
            <div
              style={{
                background: COLORS.card,
                border: `1.5px solid ${COLORS.orange}`,
                borderRadius: base * 0.006,
                padding: `${base * 0.008}px ${base * 0.014}px`,
                display: "flex",
                alignItems: "center",
                gap: base * 0.008,
                opacity: interpolate(
                  frame,
                  [80, 105],
                  [0, 1],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                ),
                transform: `translateY(${interpolate(
                  frame,
                  [80, 105],
                  [10, 0],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                )}px)`,
              }}
            >
              <div
                style={{
                  width: base * 0.012,
                  height: base * 0.012,
                  borderRadius: "50%",
                  background: COLORS.orange,
                }}
              />
              <div
                style={{
                  fontFamily: FONT_PRIMARY,
                  fontSize: base * 0.014,
                  color: COLORS.orange,
                  fontWeight: 600,
                  letterSpacing: "-0.005em",
                }}
              >
                3 need attention
              </div>
            </div>

            {/* OK badge */}
            <div
              style={{
                background: "rgba(255,255,255,0.04)",
                border: `1px solid ${COLORS.border}`,
                borderRadius: base * 0.006,
                padding: `${base * 0.008}px ${base * 0.014}px`,
                display: "flex",
                alignItems: "center",
                gap: base * 0.008,
                opacity: interpolate(
                  frame,
                  [95, 120],
                  [0, 1],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                ),
                transform: `translateY(${interpolate(
                  frame,
                  [95, 120],
                  [10, 0],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                )}px)`,
              }}
            >
              <svg
                width={base * 0.012}
                height={base * 0.012}
                viewBox="0 0 24 24"
                fill="none"
              >
                <path
                  d="M5 12.5 L10 17.5 L19 7"
                  stroke={COLORS.textMuted}
                  strokeWidth={3}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  fill="none"
                />
              </svg>
              <div
                style={{
                  fontFamily: FONT_PRIMARY,
                  fontSize: base * 0.014,
                  color: COLORS.textMuted,
                  fontWeight: 500,
                  letterSpacing: "-0.005em",
                }}
              >
                45 stable
              </div>
            </div>

            <div style={{ flex: 1 }} />

            {/* "Stays out of your way" - sleep/zen indicator */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: base * 0.008,
                opacity: peaceful,
                transform: `translateY(${interpolate(peaceful, [0, 1], [10, 0])}px)`,
              }}
            >
              <svg
                width={base * 0.018}
                height={base * 0.018}
                viewBox="0 0 24 24"
                fill="none"
              >
                <path
                  d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79Z"
                  stroke={COLORS.orange}
                  strokeWidth={2}
                  strokeLinejoin="round"
                  fill="none"
                />
              </svg>
              <div
                style={{
                  fontFamily: FONT_MONO,
                  fontSize: base * 0.012,
                  color: COLORS.textSubtle,
                  letterSpacing: "0.1em",
                  textTransform: "uppercase",
                }}
              >
                Auto
              </div>
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

